const pages=[
 {title:"Johnny Builds to Mars",text:"Johnny had a toolbox, a bright red cap, and one enormous idea: “I’m going to build my way to Mars!”",prompt:"Tap the rocket to begin!",kind:"cover"},
 {title:"A Mountain of Parts",text:"He found a silver tub, two sturdy fins, a window, and a bell. Clink! Clank! Could these become a rocket?",prompt:"Tap every part to build the rocket.",kind:"build"},
 {title:"Fuel for an Idea",text:"Johnny filled the tank with giggles, bravery, and exactly twelve scoops of imagination. The launch meter began to glow.",prompt:"Pump the yellow button until the tank is full!",kind:"fuel"},
 {title:"Ten, Nine, Eight…",text:"The rocket rumbled. The spoons danced in the kitchen drawer. Johnny held on tight and counted down.",prompt:"Tap the numbers in order: 3, 2, 1!",kind:"count"},
 {title:"A Sky Full of Sparkles",text:"Whoosh! Earth became a blue marble behind him. Ahead, the stars winked like tiny porch lights.",prompt:"Find and tap all five twinkly stars.",kind:"stars"},
 {title:"The Space Snack Test",text:"Johnny’s tummy growled. In zero gravity, his snacks floated everywhere! Which snack was shaped like the moon?",prompt:"Choose the round snack.",kind:"snack"},
 {title:"A New Martian Friend",text:"On Mars, Johnny met a shy green Martian named Pip. Pip spoke in beeps, so Johnny answered with a friendly wave.",prompt:"Tap Pip three times to teach him a happy hello.",kind:"alien"},
 {title:"A Little Piece of Home",text:"Together they planted a tiny pine seed beside the rocket. Johnny promised to visit when it grew taller than Pip.",prompt:"Tap the seed and help it grow.",kind:"grow"},
 {title:"Home Before Bedtime",text:"Johnny zoomed home with a pocket full of red dust and a brand-new friend in the stars. “Tomorrow,” he yawned, “I’ll build to Saturn.”",prompt:"Tap Johnny’s rocket for a big hooray!",kind:"end"}
];
let page=0,soundOn=true,reads=null,state={};
const $=s=>document.querySelector(s),library=$('#library'),reader=$('#reader'),scene=$('#scene');
function ping(freq=440,d=.08){if(!soundOn)return;const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.08,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+d);o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+d)}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1200)}
function openBook(){library.hidden=true;reader.hidden=false;page=0;render();window.scrollTo({top:0,behavior:'smooth'})}
function render(){speechSynthesis.cancel();reads=null;const p=pages[page];state={count:0};$('#pageTitle').textContent=p.title;$('#storyText').textContent=p.text;$('#prompt').textContent='✨ '+p.prompt;$('#pageNumber').textContent=page===0?'A Parker & Pine story':page===pages.length-1?'The end':`Page ${page} of ${pages.length-2}`;$('#pageLabel').textContent=page===0?'Cover':page===pages.length-1?'The end':`Page ${page}`;$('#progressFill').style.width=((page+1)/pages.length*100)+'%';$('#prevBtn').disabled=page===0;$('#nextBtn').innerHTML=page===pages.length-1?'<span>Again</span> ↻':'<span>Next</span> ›';drawDots();drawScene(p.kind)}
function drawDots(){const d=$('#dots');d.innerHTML='';pages.forEach((_,i)=>{const b=document.createElement('button');b.className=i===page?'active':'';b.ariaLabel='Go to '+(i===0?'cover':`page ${i}`);b.onclick=()=>{page=i;render()};d.append(b)})}
function base(){scene.innerHTML='<div class="space"></div>'}
function drawScene(k){base();if(k==='cover'){scene.insertAdjacentHTML('beforeend','<button class="tap-button big-emoji" aria-label="Wiggle the rocket">🚀</button>');scene.querySelector('button').onclick=e=>{e.currentTarget.classList.add('wiggle');ping(620);setTimeout(()=>{page++;render()},600)}}
if(k==='build'){scene.insertAdjacentHTML('beforeend','<div class="parts"><button class="part">🛢️</button><button class="part">🔺</button><button class="part">🪟</button></div><div class="rocket-build">🚀</div>');scene.querySelectorAll('.part').forEach(x=>x.onclick=()=>{if(x.classList.contains('used'))return;x.classList.add('used');state.count++;ping(330+state.count*100);if(state.count===3){scene.querySelector('.rocket-build').classList.add('ready');toast('Rocket ready!')}})}
if(k==='fuel'){scene.insertAdjacentHTML('beforeend','<button class="fuel" aria-label="Pump imagination fuel">✨</button><div class="meter"><i></i></div>');scene.querySelector('.fuel').onclick=e=>{state.count=Math.min(5,state.count+1);e.currentTarget.classList.add('wiggle');setTimeout(()=>e.currentTarget.classList.remove('wiggle'),400);scene.querySelector('.meter i').style.width=state.count*20+'%';ping(300+state.count*90);if(state.count===5)toast('Tank full!')}}
if(k==='count'){scene.insertAdjacentHTML('beforeend','<div class="moon-path"><button class="step" style="left:18%;top:58%">3</button><button class="step" style="left:44%;top:38%">2</button><button class="step" style="left:70%;top:18%">1</button></div><div class="big-emoji" style="position:absolute;bottom:7%;left:5%;font-size:7rem">🚀</div>');scene.querySelectorAll('.step').forEach((x,i)=>x.onclick=()=>{if(i!==state.count){toast('Try the next number!');return}x.classList.add('done');state.count++;ping(450+i*130);if(state.count===3){toast('BLAST OFF!');scene.querySelector('.big-emoji').style.transform='translate(340px,-300px) rotate(-20deg)'}})}
if(k==='stars'){let html='<div class="stars">';[[13,18],[74,16],[42,38],[19,70],[78,72]].forEach((a,i)=>html+=`<button class="star" style="left:${a[0]}%;top:${a[1]}%" aria-label="Star ${i+1}">✦</button>`);scene.insertAdjacentHTML('beforeend',html+'</div><div class="big-emoji" style="font-size:8rem">🌍</div>');scene.querySelectorAll('.star').forEach(x=>x.onclick=()=>{if(x.classList.contains('found'))return;x.classList.add('found');state.count++;ping(600+state.count*70);if(state.count===5)toast('You found every star!')})}
if(k==='snack'){scene.insertAdjacentHTML('beforeend','<div class="choice-row"><button class="choice" aria-label="Banana">🍌</button><button class="choice" data-good="1" aria-label="Orange">🍊</button><button class="choice" aria-label="Sandwich">🥪</button></div>');scene.querySelectorAll('.choice').forEach(x=>x.onclick=()=>{if(x.dataset.good){x.classList.add('correct');ping(720);toast('Round like the moon!')}else{ping(180);toast('Good try—look for a circle!')}})}
if(k==='alien'){scene.insertAdjacentHTML('beforeend','<button class="alien" aria-label="Wave to Pip">👽</button>');scene.querySelector('.alien').onclick=e=>{state.count++;ping(400+state.count*100);e.currentTarget.textContent=state.count<3?'👋':'👽';if(state.count===3){e.currentTarget.classList.add('happy');toast('Beep-beep! Hello, friend!')}}}
if(k==='grow'){scene.insertAdjacentHTML('beforeend','<button class="celebrate" aria-label="Grow the seed">🌰</button>');const stages=['🌰','🌱','🌿','🌲'];scene.querySelector('button').onclick=e=>{state.count=Math.min(3,state.count+1);e.currentTarget.textContent=stages[state.count];ping(420+state.count*100);if(state.count===3)toast('A Mars pine!')}}
if(k==='end'){scene.insertAdjacentHTML('beforeend','<button class="celebrate" aria-label="Celebrate the end">🚀</button>');scene.querySelector('button').onclick=e=>{e.currentTarget.classList.add('pop');ping(760,.2);for(let i=0;i<18;i++){const c=document.createElement('i');c.className='confetti';c.textContent=['★','●','▲'][i%3];c.style.left=Math.random()*90+'%';c.style.top='-10%';c.style.color=['#ffd54a','#ff6d5f','#87e2bd'][i%3];c.style.animationDelay=Math.random()*.5+'s';scene.append(c)}toast('Hooray—you finished the story!')}}}
$('#openBook').onclick=$('#startBtn').onclick=openBook;$('#shelfBtn').onclick=$('#homeBtn').onclick=()=>{speechSynthesis.cancel();reader.hidden=true;library.hidden=false};$('#prevBtn').onclick=()=>{if(page>0){page--;render()}};$('#nextBtn').onclick=()=>{page=page===pages.length-1?0:page+1;render()};$('#soundBtn').onclick=e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'🔊':'🔇';e.currentTarget.ariaPressed=String(soundOn);e.currentTarget.ariaLabel=soundOn?'Turn sounds off':'Turn sounds on'};$('#readBtn').onclick=()=>{if(reads){speechSynthesis.cancel();reads=null;$('#readBtn').textContent='▶ Read to me';return}reads=new SpeechSynthesisUtterance(pages[page].title+'. '+pages[page].text);reads.rate=.82;reads.pitch=1.12;reads.onend=()=>{reads=null;$('#readBtn').textContent='▶ Read to me'};speechSynthesis.speak(reads);$('#readBtn').textContent='■ Stop reading'};
document.addEventListener('keydown',e=>{if(reader.hidden)return;if(e.key==='ArrowRight')$('#nextBtn').click();if(e.key==='ArrowLeft')$('#prevBtn').click()});
